// SPDX-License-Identifier: Apache-2.0
//! `war mcp` — the Model Context Protocol server over stdio (OW-ADR-0014).
//!
//! The only place in this workspace where an async runtime exists. Every tool
//! body is a synchronous call into the module that already implements the
//! command; the runtime drives the transport and nothing else. Nothing here
//! can authorize, resolve, verify, accept, sign or ingest a response: those
//! are human acts (§27.2), and the tool table is asserted against a refusal
//! list in this module's tests.
//!
//! Stdout belongs to the transport. No function reached from a tool may print;
//! the two commands whose printers live in pinned files (`war compile`,
//! `war sign --show`) are run as a child process with stdout captured.

mod resources;
mod tools;

use std::sync::Arc;

use rmcp::ServerHandler;
use rmcp::handler::server::tool::ToolRouter;
use rmcp::model::{
    ErrorData as McpError, ListResourcesResult, PaginatedRequestParams, ReadResourceRequestParams,
    ReadResourceResponse, ServerCapabilities, ServerInfo,
};
use rmcp::service::{RequestContext, RoleServer};

use crate::repo::{RepoError, Repository};

/// What the server tells a client at `initialize`. Verbatim non-authority:
/// an agent reading this knows whose act is whose before it calls anything.
pub const INSTRUCTIONS: &str = "OpenWarrant (`war`) MCP server. It reads and drafts Work \
Authorization Records for a repository; it holds NO authority. It cannot authorize, resolve, \
verify, accept a SAS, correct a delivered artifact, or sign anything, and no tool ingests a \
signed response: those are human acts done at a terminal with `war sign`. Tools ending in \
`_request` emit the document a human will sign; they write nothing. `war_next` says whose \
action comes next and whether it is the agent's or a human's. `war_pins` lists the files an \
agent may not edit (pinned by resolved Warrants). Every tool returns an `oh.war/report/v1` \
envelope as structured content: `diagnostics[]` name a rule per finding, `verdict` is \
ready|not_ready, `exit_code` is what the CLI would have exited with. Tickets need none of the \
authority acts: start with `war_prime`, pick from `war_ready`, `war_claim` an item, do it, \
`war_done` it; `war_create`, `war_add` and `war_note` keep the ticket's document current. Never \
ask a human to sign during that work.";

/// Tool names the server must never register. Asserted by a test below
/// against the live router, and by a source grep against `tools.rs`.
pub const REFUSED_TOOLS: &[&str] = &[
    "war_sign",
    "war_sign_ssh",
    "war_authorize",
    "war_authorize_ingest",
    "war_resolve",
    "war_resolve_ingest",
    "war_verify",
    "war_verify_ingest",
    "war_correct",
    "war_correct_ingest",
    "war_sas_accept",
    "war_sas_accept_ingest",
    "war_sas_propose",
    "war_kf",
    "war_telemetry",
    "war_migrate",
    "war_export",
    "war_bonsai",
    "war_eval",
    // An agent asks (war_ask); only a human answers.
    "war_answer",
    "war_init",
    "war_gate_record",
    "war_plan_draft",
    // OW-ADR-0029: a class is proposed at the CLI and signed, accepted,
    // revoked or ingested only by a human.
    "war_standing_propose_ingest",
    "war_standing_accept",
    "war_standing_revoke",
    "war_standing_ingest",
];

/// The server: one repository, one tool table.
#[derive(Clone)]
pub struct WarServer {
    repo: Arc<Repository>,
    tool_router: ToolRouter<Self>,
}

impl WarServer {
    #[must_use]
    pub fn new(repo: Repository) -> Self {
        Self {
            repo: Arc::new(repo),
            tool_router: Self::tool_router(),
        }
    }

    /// Every registered tool name, sorted — for the refusal test and `--list`.
    #[must_use]
    pub fn tool_names(&self) -> Vec<String> {
        let mut names: Vec<String> = self
            .tool_router
            .list_all()
            .into_iter()
            .map(|t| t.name.to_string())
            .collect();
        names.sort();
        names
    }
}

#[rmcp::tool_handler(router = self.tool_router)]
impl ServerHandler for WarServer {
    fn get_info(&self) -> ServerInfo {
        let mut info = ServerInfo::new(
            ServerCapabilities::builder()
                .enable_tools()
                .enable_resources()
                .build(),
        )
        .with_instructions(INSTRUCTIONS);
        info.server_info = rmcp::model::Implementation::new("war", env!("CARGO_PKG_VERSION"));
        info
    }

    fn list_resources(
        &self,
        _request: Option<PaginatedRequestParams>,
        _context: RequestContext<RoleServer>,
    ) -> impl std::future::Future<Output = Result<ListResourcesResult, McpError>> + Send + '_ {
        std::future::ready(resources::list(&self.repo))
    }

    fn read_resource(
        &self,
        request: ReadResourceRequestParams,
        _context: RequestContext<RoleServer>,
    ) -> impl std::future::Future<Output = Result<ReadResourceResponse, McpError>> + Send + '_ {
        std::future::ready(
            resources::read(&self.repo, &request.uri).map(ReadResourceResponse::Complete),
        )
    }
}

/// Serve on stdio until the client closes the pipe. The runtime is built here
/// and dropped here; `Repository::discover` ran before it existed.
pub fn run(repo: Repository) -> Result<(), RepoError> {
    let server = WarServer::new(repo);
    // stdin/stdout go through tokio's blocking pool, not the reactor, so no
    // driver is needed; `enable_all` enables whatever the enabled features
    // provide and nothing more.
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .map_err(|e| RepoError::Message(format!("mcp: could not start the runtime: {e}")))?;
    runtime.block_on(async move {
        let service = rmcp::serve_server(server, rmcp::transport::io::stdio())
            .await
            .map_err(|e| RepoError::Message(format!("mcp: initialize failed: {e}")))?;
        service
            .waiting()
            .await
            .map_err(|e| RepoError::Message(format!("mcp: transport task failed: {e}")))?;
        Ok(())
    })
}

/// Print the tool table and the refusal list without serving — what an
/// operator reads to know what an agent can and cannot do here.
pub fn describe(repo: Repository) -> String {
    let server = WarServer::new(repo);
    let mut out = format!("tools ({}):\n", server.tool_names().len());
    let mut tools = server.tool_router.list_all();
    tools.sort_by(|a, b| a.name.cmp(&b.name));
    for t in tools {
        out.push_str(&format!(
            "  {:<24} {}\n",
            t.name,
            t.description.as_deref().unwrap_or("")
        ));
    }
    out.push_str("never registered (human acts, or out of scope for an agent):\n");
    for r in REFUSED_TOOLS {
        out.push_str(&format!("  {r}\n"));
    }
    out.push_str("resources: warrant://<alias>[/status|/journal], status://corpus, sas://current, pins://all, next://\n");
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn repo() -> Repository {
        Repository::discover(Some(
            camino::Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../.."),
        ))
        .expect("this repository is an OpenWarrant repository")
    }

    #[test]
    fn no_refused_tool_is_registered_and_no_signing_or_ingesting_name_exists() {
        let names = WarServer::new(repo()).tool_names();
        assert!(names.len() >= 20, "{names:?}");
        for r in REFUSED_TOOLS {
            assert!(!names.iter().any(|n| n == r), "{r} is registered");
        }
        // A signing act under any spelling.
        for n in &names {
            assert!(
                !n.contains("sign") || n == "war_sign_list" || n == "war_sign_show",
                "{n}"
            );
            assert!(!n.contains("ingest"), "{n}");
        }
    }

    /// The source of the tool table names no ingest, sign or propose function.
    /// Defence in depth behind the router-level test above: it skips `//`
    /// lines and not block comments, which is fine for a second line of
    /// defence — the first one reads the live router.
    #[test]
    fn tools_source_never_calls_an_authority_seam() {
        let src = include_str!("tools.rs");
        for needle in [
            "::ingest(",
            "accept_ingest",
            "sign::run(",
            "sign::draft(",
            "sas::propose",
            "standing_cmd::propose",
            "accept_ingest_with",
            "revoke_ingest_with",
            "kf::",
            "telemetry::",
            "migrate::",
            "export::",
            "bonsai::",
            "init::",
            "record: true",
            "run_drafter",
            "println!",
            "print!(",
        ] {
            assert!(
                !src.lines()
                    .any(|l| !l.trim_start().starts_with("//") && l.contains(needle)),
                "tools.rs reaches {needle}"
            );
        }
    }

    #[test]
    fn instructions_state_non_authority_verbatim() {
        for phrase in ["cannot authorize", "sign anything", "human acts"] {
            assert!(INSTRUCTIONS.contains(phrase), "{phrase}");
        }
    }
}

// SPDX-License-Identifier: Apache-2.0
//! The ticket loop end to end (OW-WAR-0147), through the shipped binary and
//! through `war mcp`: create → ready → claim → done with no signature and no
//! human act, claims that exactly one of several processes wins, and a
//! ticket that `war check` validates for structure and nothing else.

use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Output, Stdio};

fn scratch(tag: &str) -> PathBuf {
    let root = std::env::temp_dir().join(format!(
        "ow-tickets-{tag}-{}-{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));
    std::fs::create_dir_all(&root).unwrap();
    assert!(
        Command::new("git")
            .args(["init", "-q", "."])
            .current_dir(&root)
            .status()
            .unwrap()
            .success()
    );
    let out = war(
        &root,
        &[
            "init",
            "--namespace",
            "TK",
            "--root",
            root.to_str().unwrap(),
        ],
    );
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    root
}

fn war(root: &Path, args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_war"))
        .current_dir(root)
        .env("OPENWARRANT_NO_PROJECTS", "1")
        .env("OPENWARRANT_NO_UPDATE_CHECK", "1")
        .env_remove("OPENWARRANT_ACTOR")
        .env_remove("SSH_AUTH_SOCK")
        .args(args)
        .output()
        .unwrap()
}

fn json(root: &Path, args: &[&str]) -> serde_json::Value {
    let mut all = vec!["--json"];
    all.extend_from_slice(args);
    let out = war(root, &all);
    serde_json::from_slice(&out.stdout).unwrap_or_else(|e| {
        panic!(
            "{args:?}: not an envelope ({e}): {}{}",
            String::from_utf8_lossy(&out.stdout),
            String::from_utf8_lossy(&out.stderr)
        )
    })
}

#[test]
fn create_ready_claim_done_needs_no_signature_and_no_human() {
    let root = scratch("loop");
    let created = json(
        &root,
        &["create", "Ship it", "--item", "one", "--item", "two"],
    );
    assert_eq!(created["exit_code"], 0, "{created}");
    let id = created["result"]["id"].as_str().unwrap().to_owned();
    assert!(id.starts_with("t-"));

    let ready = json(&root, &["ready"]);
    let rows = ready["result"]["ready"].as_array().unwrap();
    assert_eq!(rows.len(), 2);
    let first = format!("{id}/{}", rows[0]["item"].as_str().unwrap());

    for step in [
        vec!["claim", first.as_str()],
        vec!["done", first.as_str(), "--note", "did one"],
    ] {
        let v = json(&root, &step);
        assert_eq!(v["exit_code"], 0, "{step:?}: {v}");
    }
    let second = json(&root, &["ready"])["result"]["ready"][0]["item"]
        .as_str()
        .unwrap()
        .to_owned();
    assert_eq!(json(&root, &["claim", &second])["exit_code"], 0);
    let done = json(&root, &["done", &second]);
    assert_eq!(done["result"]["ticket_state"], "done", "{done}");

    // The file is the state: both boxes ticked, by whom and when.
    let checklist =
        std::fs::read_to_string(root.join(format!("docs/tickets/{id}/atoms/15-checklist.md")))
            .unwrap();
    assert_eq!(checklist.matches("- [x] ").count(), 2, "{checklist}");
    assert!(checklist.contains("— done by claude, "), "{checklist}");
    assert!(checklist.contains(": did one"), "{checklist}");

    // Nothing asked for a signature, and nothing was signed.
    let tree: Vec<String> = walk(&root.join("docs/tickets"));
    assert!(
        !tree
            .iter()
            .any(|p| p.contains("authorization") || p.contains("resolution") || p.contains(".sig")),
        "{tree:?}"
    );
    // `war check` reads the ticket for structure only: no finding about a
    // missing authorization, evidence or verification.
    let check = json(&root, &["check", &id]);
    assert_eq!(check["exit_code"], 0, "{check}");
    assert!(
        check["diagnostics"]
            .as_array()
            .unwrap()
            .iter()
            .all(|d| d["rule"] == "ticket.well-formed"),
        "{check}"
    );
    let _ = std::fs::remove_dir_all(&root);
}

fn walk(dir: &Path) -> Vec<String> {
    let mut out = Vec::new();
    for entry in std::fs::read_dir(dir).into_iter().flatten().flatten() {
        let p = entry.path();
        if p.is_dir() {
            out.extend(walk(&p));
        } else {
            out.push(p.display().to_string());
        }
    }
    out
}

/// Twelve `war claim` processes started together on one item: exactly one
/// exits 0, and every other one is refused naming the winner.
#[test]
fn of_concurrent_claim_processes_exactly_one_wins() {
    let root = scratch("race");
    let created = json(&root, &["create", "Race", "--item", "the only item"]);
    let id = created["result"]["id"].as_str().unwrap().to_owned();
    let item = created["result"]["items"][0]["id"]
        .as_str()
        .unwrap()
        .to_owned();
    let target = format!("{id}/{item}");
    let children: Vec<(String, std::process::Child)> = (0..12)
        .map(|n| {
            let actor = format!("agent-{n}");
            let child = Command::new(env!("CARGO_BIN_EXE_war"))
                .current_dir(&root)
                .env("OPENWARRANT_NO_PROJECTS", "1")
                .env("OPENWARRANT_NO_UPDATE_CHECK", "1")
                .args(["claim", &target, "--as", &actor])
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .unwrap();
            (actor, child)
        })
        .collect();
    let results: Vec<(String, Output)> = children
        .into_iter()
        .map(|(a, c)| (a, c.wait_with_output().unwrap()))
        .collect();
    let winners: Vec<&String> = results
        .iter()
        .filter(|(_, o)| o.status.success())
        .map(|(a, _)| a)
        .collect();
    assert_eq!(winners.len(), 1, "{winners:?}");
    for (actor, out) in &results {
        if !out.status.success() {
            let err = String::from_utf8_lossy(&out.stderr);
            assert!(
                err.contains("ticket.claimed-by-other") && err.contains(winners[0].as_str()),
                "{actor}: {err}"
            );
        }
    }
    // The winner's claim is journalled once.
    let journal =
        std::fs::read_to_string(root.join(format!("docs/tickets/{id}/journal.jsonl"))).unwrap();
    assert_eq!(
        journal.matches("\"ticket.claimed\"").count(),
        1,
        "{journal}"
    );
    let _ = std::fs::remove_dir_all(&root);
}

/// t-9d3e: once `war done` on a blocker has exited 0, `war ready` lists the
/// item it held and `war claim` takes it — never one without the other. Four
/// workers on one corpus, ten rounds each, every command's exit checked by
/// name so a step that failed cannot pass for the two disagreeing.
#[test]
fn after_done_ready_and_claim_agree_under_concurrency() {
    let root = scratch("agree");
    let workers: Vec<_> = (0..4)
        .map(|w| {
            let root = root.clone();
            std::thread::spawn(move || {
                let actor = format!("worker-{w}");
                let step = |args: &[&str]| -> serde_json::Value {
                    let mut all = vec!["--json"];
                    all.extend_from_slice(args);
                    all.extend_from_slice(&["--as", &actor]);
                    let out = war(&root, &all);
                    assert!(
                        out.status.success(),
                        "{actor}: {args:?} exited {:?}: {}{}",
                        out.status.code(),
                        String::from_utf8_lossy(&out.stdout),
                        String::from_utf8_lossy(&out.stderr)
                    );
                    serde_json::from_slice(&out.stdout).unwrap()
                };
                for n in 0..10 {
                    let title = format!("{actor} round {n}");
                    let created = step(&["create", &title, "--item", "Foundation"]);
                    let t = created["result"]["id"].as_str().unwrap().to_owned();
                    let f = created["result"]["items"][0]["id"]
                        .as_str()
                        .unwrap()
                        .to_owned();
                    let added = step(&["add", &t, "Walls", "--after", &f]);
                    let walls = added["result"]["item"].as_str().unwrap().to_owned();
                    step(&["claim", &format!("{t}/{f}")]);
                    step(&["done", &format!("{t}/{f}")]);
                    let ready = step(&["ready"]);
                    let listed = ready["result"]["ready"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .any(|r| r["ticket"] == t.as_str() && r["item"] == walls.as_str());
                    assert!(
                        listed,
                        "{actor}: {t}/{walls} not ready once its blocker was done"
                    );
                    step(&["claim", &format!("{t}/{walls}")]);
                }
            })
        })
        .collect();
    for w in workers {
        w.join().unwrap();
    }
    let _ = std::fs::remove_dir_all(&root);
}

/// An unsigned ticket is a normal working state: `war check` on a program
/// holding one reports no error for it, and a malformed checklist is named.
#[test]
fn check_validates_structure_and_never_asks_for_authority() {
    let root = scratch("check");
    let id = json(&root, &["create", "Checked", "--item", "a"])["result"]["id"]
        .as_str()
        .unwrap()
        .to_owned();
    let whole = json(&root, &["check"]);
    let errors: Vec<&serde_json::Value> = whole["diagnostics"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|d| d["severity"] == "error")
        .collect();
    assert!(errors.is_empty(), "{errors:?}");
    let path = root.join(format!("docs/tickets/{id}/atoms/15-checklist.md"));
    let mut text = std::fs::read_to_string(&path).unwrap();
    text.push_str("- [?] what is this\n");
    std::fs::write(&path, text).unwrap();
    let bad = json(&root, &["check", &id]);
    assert_eq!(bad["exit_code"], 2, "{bad}");
    assert!(
        bad["diagnostics"]
            .as_array()
            .unwrap()
            .iter()
            .any(|d| d["rule"] == "ticket.checklist-malformed"),
        "{bad}"
    );
    let _ = std::fs::remove_dir_all(&root);
}

struct Mcp {
    child: std::process::Child,
    out: BufReader<std::process::ChildStdout>,
    next: u64,
}

impl Mcp {
    fn start(root: &Path) -> Self {
        let mut child = Command::new(env!("CARGO_BIN_EXE_war"))
            .arg("mcp")
            .current_dir(root)
            .env("OPENWARRANT_NO_PROJECTS", "1")
            .env("OPENWARRANT_NO_UPDATE_CHECK", "1")
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap();
        let out = BufReader::new(child.stdout.take().unwrap());
        let mut s = Self {
            child,
            out,
            next: 1,
        };
        s.call(
            "initialize",
            serde_json::json!({"protocolVersion":"2025-06-18","capabilities":{},
                "clientInfo":{"name":"test","version":"0"}}),
        );
        s.send(serde_json::json!({"jsonrpc":"2.0","method":"notifications/initialized"}));
        s
    }

    fn send(&mut self, v: serde_json::Value) {
        let stdin = self.child.stdin.as_mut().unwrap();
        stdin.write_all(format!("{v}\n").as_bytes()).unwrap();
        stdin.flush().unwrap();
    }

    fn call(&mut self, method: &str, params: serde_json::Value) -> serde_json::Value {
        let id = self.next;
        self.next += 1;
        self.send(serde_json::json!({"jsonrpc":"2.0","id":id,"method":method,"params":params}));
        let mut line = String::new();
        self.out.read_line(&mut line).unwrap();
        serde_json::from_str(&line).unwrap()
    }

    fn tool(&mut self, name: &str, args: serde_json::Value) -> serde_json::Value {
        let v = self.call(
            "tools/call",
            serde_json::json!({"name": name, "arguments": args}),
        );
        v["result"]["structuredContent"].clone()
    }
}

impl Drop for Mcp {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

#[test]
fn an_agent_works_a_ticket_over_mcp() {
    let root = scratch("mcp");
    let mut mcp = Mcp::start(&root);
    let names: Vec<String> = mcp.call("tools/list", serde_json::json!({}))["result"]["tools"]
        .as_array()
        .unwrap()
        .iter()
        .map(|t| t["name"].as_str().unwrap().to_owned())
        .collect();
    for want in [
        "war_create",
        "war_ready",
        "war_claim",
        "war_done",
        "war_add",
        "war_note",
        "war_prime",
        "war_show",
        "war_tickets",
    ] {
        assert!(names.iter().any(|n| n == want), "{want} in {names:?}");
    }
    let created = mcp.tool(
        "war_create",
        serde_json::json!({"title": "Over MCP", "items": ["first"]}),
    );
    let id = created["result"]["id"].as_str().unwrap().to_owned();
    let item = created["result"]["items"][0]["id"]
        .as_str()
        .unwrap()
        .to_owned();
    let target = format!("{id}/{item}");
    assert_eq!(
        mcp.tool("war_claim", serde_json::json!({"target": target}))["exit_code"],
        0
    );
    // A second agent is refused by name.
    let other = mcp.tool(
        "war_claim",
        serde_json::json!({"target": target, "actor": "other"}),
    );
    assert_eq!(other["exit_code"], 2, "{other}");
    assert!(
        other["diagnostics"][0]["message"]
            .as_str()
            .unwrap()
            .contains("claude")
    );
    let added = mcp.tool(
        "war_add",
        serde_json::json!({"ticket": id, "text": "second", "after": [item]}),
    );
    assert_eq!(added["exit_code"], 0, "{added}");
    let noted = mcp.tool("war_note", serde_json::json!({"target": id, "text": "why"}));
    assert_eq!(noted["exit_code"], 0, "{noted}");
    let done = mcp.tool(
        "war_done",
        serde_json::json!({"target": target, "note": "ok"}),
    );
    assert_eq!(done["result"]["progress"]["done"], 1, "{done}");
    let prime = mcp.tool("war_prime", serde_json::json!({}));
    let md = prime["result"]["markdown"].as_str().unwrap();
    assert!(md.contains("second") && !md.contains("- [ ] first"), "{md}");
    let shown = mcp.tool("war_show", serde_json::json!({"alias": id}));
    assert!(
        shown["result"]["markdown"]
            .as_str()
            .unwrap()
            .contains("## Checklist")
    );
    let _ = std::fs::remove_dir_all(&root);
}
